#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""No-args biological profile of samples helped or hurt by mRNA-LM + XGB late fusion."""

from __future__ import annotations

import json
import math
import os
from datetime import datetime
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd


# =============================================================================
# CONFIG: paths are resolved from environment first. Point these to the clean
# late-fusion run generated by script 17.
# =============================================================================
def env_path(name: str, default: Path | str) -> Path:
    value = os.environ.get(name, "").strip()
    return Path(value) if value else Path(default)


def env_str(name: str, default: str) -> str:
    value = os.environ.get(name, "").strip()
    return value if value else default


PROJECT_ROOT = env_path("SALUKI_PROJECT_ROOT", Path(__file__).resolve().parents[2])
RUNS_ROOT = env_path("SALUKI_RUNS_ROOT", PROJECT_ROOT / "results" / "runs")

LATE_FUSION_RUN_ROOT = env_path(
    "SALUKI_FUSION_GAIN_LATE_FUSION_RUN_ROOT",
    RUNS_ROOT / "late_fusion",
)
LATE_FUSION_PRED_TEST_PATH = env_path(
    "SALUKI_FUSION_GAIN_LATE_FUSION_PRED_TEST_PATH",
    LATE_FUSION_RUN_ROOT / "late_fusion_pred_test.csv",
)

BASIC_FEATURE_PATH = env_path(
    "SALUKI_FUSION_GAIN_BASIC_FEATURE_PATH",
    os.environ.get(
        "SALUKI_GENETIC_BIOCHEMICAL_PATH",
        PROJECT_ROOT / "data" / "saluki_features" / "human" / "alldataGeneticBiochemical.tsv.gz",
    ),
)

OUT_BASE_DIR = env_path("SALUKI_FUSION_GAIN_OUT_BASE_DIR", RUNS_ROOT)
RUN_TAG = env_str("SALUKI_FUSION_GAIN_RUN_TAG", "fusion_gain")
OUT_DIR = OUT_BASE_DIR / RUN_TAG

XGB_METHOD = "xgb_only"
MRNALM_METHOD = "mrnalm_only"
FUSION_METHOD = "linear_fusion"
TOP_FRACTION = 0.20

PROFILE_FEATURES = [
    "HALFLIFE",
    "BASIC.UTR5LEN",
    "BASIC.CDSLEN",
    "BASIC.INTRONLEN",
    "BASIC.UTR3LEN",
    "BASIC.UTR5GC",
    "BASIC.CDSGC",
    "BASIC.UTR3GC",
    "BASIC.ORFEXONDENSITY",
    "xgb_pred",
    "mrnalm_pred",
    "fusion_pred",
    "xgb_residual",
    "fusion_residual",
    "abs_err_xgb",
    "abs_err_fusion",
    "fusion_gain",
]


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def config_dict() -> dict[str, Any]:
    return {
        "script_path": str(Path(__file__).resolve()),
        "timestamp": now_iso(),
        "project_root": str(PROJECT_ROOT),
        "late_fusion_run_root": str(LATE_FUSION_RUN_ROOT),
        "late_fusion_pred_test_path": str(LATE_FUSION_PRED_TEST_PATH),
        "basic_feature_path": str(BASIC_FEATURE_PATH),
        "out_base_dir": str(OUT_BASE_DIR),
        "run_tag": RUN_TAG,
        "out_dir": str(OUT_DIR),
        "xgb_method": XGB_METHOD,
        "mrnalm_method": MRNALM_METHOD,
        "fusion_method": FUSION_METHOD,
        "top_fraction": TOP_FRACTION,
        "profile_features": list(PROFILE_FEATURES),
    }


def print_config_and_raise(message: str) -> None:
    print("[CONFIG]", flush=True)
    print(json.dumps(config_dict(), indent=2, ensure_ascii=False), flush=True)
    raise FileNotFoundError(message)


def validate_config_paths() -> None:
    required = {
        "PROJECT_ROOT": PROJECT_ROOT,
        "LATE_FUSION_PRED_TEST_PATH": LATE_FUSION_PRED_TEST_PATH,
        "BASIC_FEATURE_PATH": BASIC_FEATURE_PATH,
    }
    missing = {name: str(path) for name, path in required.items() if not path.exists()}
    if missing:
        print_config_and_raise(f"Missing CONFIG path(s): {missing}")


def write_json(path: Path, payload: dict[str, Any]) -> None:
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def bh_fdr(p_values: pd.Series | np.ndarray) -> np.ndarray:
    p = pd.to_numeric(pd.Series(p_values), errors="coerce").to_numpy(dtype=np.float64)
    q = np.full(p.shape, np.nan, dtype=np.float64)
    valid = np.isfinite(p)
    if int(valid.sum()) == 0:
        return q
    pv = p[valid]
    order = np.argsort(pv)
    ranked = pv[order]
    m = float(len(ranked))
    adjusted = ranked * m / np.arange(1, len(ranked) + 1, dtype=np.float64)
    adjusted = np.minimum.accumulate(adjusted[::-1])[::-1]
    adjusted = np.clip(adjusted, 0.0, 1.0)
    out = np.empty_like(pv)
    out[order] = adjusted
    q[valid] = out
    return q


def finite_corr(x: np.ndarray, y: np.ndarray, ranked: bool = False) -> float:
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    mask = np.isfinite(x) & np.isfinite(y)
    if int(mask.sum()) < 3:
        return float("nan")
    x = x[mask]
    y = y[mask]
    if ranked:
        x = pd.Series(x).rank(method="average").to_numpy(dtype=np.float64)
        y = pd.Series(y).rank(method="average").to_numpy(dtype=np.float64)
    if np.nanstd(x) == 0 or np.nanstd(y) == 0:
        return float("nan")
    return float(np.corrcoef(x, y)[0, 1])


def r2_np(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    y_true = np.asarray(y_true, dtype=np.float64)
    y_pred = np.asarray(y_pred, dtype=np.float64)
    ss_res = float(np.sum((y_true - y_pred) ** 2))
    ss_tot = float(np.sum((y_true - y_true.mean()) ** 2))
    if ss_tot == 0:
        return float("nan")
    return 1.0 - ss_res / ss_tot


def metrics(y_true: np.ndarray, y_pred: np.ndarray) -> dict[str, float]:
    y_true = np.asarray(y_true, dtype=np.float64)
    y_pred = np.asarray(y_pred, dtype=np.float64)
    return {
        "r2": r2_np(y_true, y_pred),
        "pearson": finite_corr(y_true, y_pred, ranked=False),
        "spearman": finite_corr(y_true, y_pred, ranked=True),
        "rmse": float(np.sqrt(np.mean((y_true - y_pred) ** 2))),
        "mae": float(np.mean(np.abs(y_true - y_pred))),
    }


def try_mannwhitneyu(x: np.ndarray, y: np.ndarray) -> float:
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    x = x[np.isfinite(x)]
    y = y[np.isfinite(y)]
    if len(x) == 0 or len(y) == 0:
        return float("nan")
    try:
        from scipy.stats import mannwhitneyu  # type: ignore

        return float(mannwhitneyu(x, y, alternative="two-sided").pvalue)
    except Exception:
        return float("nan")


def cliffs_delta(x: np.ndarray, y: np.ndarray, max_pairs: int = 2_000_000) -> float:
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    x = x[np.isfinite(x)]
    y = y[np.isfinite(y)]
    if len(x) == 0 or len(y) == 0:
        return float("nan")
    n_pairs = len(x) * len(y)
    if n_pairs > max_pairs:
        rng = np.random.default_rng(42)
        xi = rng.choice(x, size=int(math.sqrt(max_pairs)), replace=True)
        yi = rng.choice(y, size=int(math.sqrt(max_pairs)), replace=True)
        x = xi
        y = yi
    diff = x[:, None] - y[None, :]
    return float((np.sum(diff > 0) - np.sum(diff < 0)) / diff.size)


def load_late_fusion_predictions() -> pd.DataFrame:
    df = pd.read_csv(LATE_FUSION_PRED_TEST_PATH)
    required = {"sample_id", "cv_fold", "method", "y_true", "y_pred", "xgb_pred", "mrnalm_pred"}
    missing = sorted(required.difference(df.columns))
    if missing:
        raise ValueError(f"late fusion prediction file missing required columns: {missing}")
    needed_methods = {XGB_METHOD, MRNALM_METHOD, FUSION_METHOD}
    missing_methods = sorted(needed_methods.difference(set(df["method"].astype(str))))
    if missing_methods:
        raise ValueError(f"late fusion prediction file missing methods: {missing_methods}")
    key_cols = ["sample_id", "cv_fold"]
    base = df.loc[df["method"].astype(str) == XGB_METHOD, key_cols + ["y_true", "xgb_pred", "mrnalm_pred"]].copy()
    mrnalm = df.loc[df["method"].astype(str) == MRNALM_METHOD, key_cols + ["y_pred"]].rename(columns={"y_pred": "mrnalm_only_pred"})
    fusion = df.loc[df["method"].astype(str) == FUSION_METHOD, key_cols + ["y_pred"]].rename(columns={"y_pred": "fusion_pred"})
    out = base.merge(mrnalm, on=key_cols, how="inner").merge(fusion, on=key_cols, how="inner")
    if out.duplicated(key_cols).any():
        dup = out.loc[out.duplicated(key_cols), key_cols].head(10).to_dict("records")
        raise ValueError(f"Duplicated sample/fold rows after merge, examples={dup}")
    out["xgb_pred"] = pd.to_numeric(out["xgb_pred"], errors="coerce")
    out["mrnalm_pred"] = pd.to_numeric(out["mrnalm_pred"], errors="coerce")
    out["fusion_pred"] = pd.to_numeric(out["fusion_pred"], errors="coerce")
    return out


def load_basic_features(ids: list[str]) -> pd.DataFrame:
    usecols = ["GENEID", "HALFLIFE", *[c for c in PROFILE_FEATURES if c.startswith("BASIC.")]]
    df = pd.read_csv(
        BASIC_FEATURE_PATH,
        sep="\t",
        compression="infer",
        usecols=usecols,
        dtype={"GENEID": "string"},
        low_memory=False,
    )
    df["sample_id"] = df["GENEID"].astype(str)
    df = df.drop(columns=["GENEID"])
    for col in df.columns:
        if col != "sample_id":
            df[col] = pd.to_numeric(df[col], errors="coerce")
    return df[df["sample_id"].isin(ids)].copy()


def assign_gain_groups(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    lo = out["fusion_gain"].quantile(TOP_FRACTION)
    hi = out["fusion_gain"].quantile(1.0 - TOP_FRACTION)
    out["fusion_gain_group"] = "neutral_middle60"
    out.loc[out["fusion_gain"] >= hi, "fusion_gain_group"] = "fusion_helped_top20"
    out.loc[out["fusion_gain"] <= lo, "fusion_gain_group"] = "fusion_hurt_top20"

    labels = []
    for _, sub in out.groupby("cv_fold", sort=False):
        f_lo = sub["fusion_gain"].quantile(TOP_FRACTION)
        f_hi = sub["fusion_gain"].quantile(1.0 - TOP_FRACTION)
        fold_label = pd.Series("neutral_middle60", index=sub.index)
        fold_label.loc[sub["fusion_gain"] >= f_hi] = "fusion_helped_top20"
        fold_label.loc[sub["fusion_gain"] <= f_lo] = "fusion_hurt_top20"
        labels.append(fold_label)
    out["fusion_gain_group_within_fold"] = pd.concat(labels).sort_index()
    return out


def summarize_groups(df: pd.DataFrame, group_col: str) -> pd.DataFrame:
    if group_col not in df.columns:
        raise ValueError(f"Missing group_col={group_col!r}")
    rows: list[dict[str, Any]] = []
    for group, sub in df.groupby(group_col, sort=False):
        row: dict[str, Any] = {"group_col": group_col, "fusion_gain_group": group, "n": len(sub)}
        for col in PROFILE_FEATURES:
            if col not in sub.columns:
                continue
            values = pd.to_numeric(sub[col], errors="coerce")
            row[f"{col}_mean"] = float(values.mean())
            row[f"{col}_median"] = float(values.median())
            row[f"{col}_q25"] = float(values.quantile(0.25))
            row[f"{col}_q75"] = float(values.quantile(0.75))
        for name, pred_col in (("xgb", "xgb_pred"), ("mrnalm", "mrnalm_pred"), ("fusion", "fusion_pred")):
            for metric, value in metrics(sub["y_true"].to_numpy(), sub[pred_col].to_numpy()).items():
                row[f"{name}_{metric}"] = value
        rows.append(row)
    return pd.DataFrame(rows)


def helped_vs_hurt_stats(df: pd.DataFrame, group_col: str) -> pd.DataFrame:
    if group_col not in df.columns:
        raise ValueError(f"Missing group_col={group_col!r}")
    helped = df[df[group_col] == "fusion_helped_top20"]
    hurt = df[df[group_col] == "fusion_hurt_top20"]
    rows = []
    for col in PROFILE_FEATURES:
        if col not in df.columns:
            continue
        x = pd.to_numeric(helped[col], errors="coerce").to_numpy(np.float64)
        y = pd.to_numeric(hurt[col], errors="coerce").to_numpy(np.float64)
        rows.append(
            {
                "feature": col,
                "group_col": group_col,
                "helped_median": float(np.nanmedian(x)),
                "hurt_median": float(np.nanmedian(y)),
                "median_difference_helped_minus_hurt": float(np.nanmedian(x) - np.nanmedian(y)),
                "mannwhitney_p": try_mannwhitneyu(x, y),
                "cliffs_delta_helped_vs_hurt": cliffs_delta(x, y),
                "n_helped": int(np.isfinite(x).sum()),
                "n_hurt": int(np.isfinite(y).sum()),
            }
        )
    out = pd.DataFrame(rows).sort_values("feature")
    out["q_value_bh_fdr"] = bh_fdr(out["mannwhitney_p"])
    return out


def try_import_matplotlib():
    try:
        import matplotlib.pyplot as plt  # type: ignore

        return plt
    except Exception as exc:
        print(f"[WARN] matplotlib unavailable; skipping plots: {exc}", flush=True)
        return None


def save_plots(df: pd.DataFrame, stats: pd.DataFrame) -> None:
    plt = try_import_matplotlib()
    if plt is None:
        return
    fig, ax = plt.subplots(figsize=(7, 4))
    ax.hist(df["fusion_gain"], bins=50, color="#4f83b1", alpha=0.85)
    ax.axvline(0, color="black", linewidth=0.8)
    ax.set_xlabel("Fusion gain = |err XGB| - |err fusion|")
    ax.set_ylabel("Number of transcripts")
    ax.set_title("Distribution of fusion gain")
    fig.tight_layout()
    for ext in ("png", "pdf"):
        fig.savefig(OUT_DIR / f"fusion_gain_distribution.{ext}", dpi=220)
    plt.close(fig)

    selected = [
        "HALFLIFE",
        "BASIC.UTR3LEN",
        "BASIC.CDSLEN",
        "BASIC.ORFEXONDENSITY",
        "BASIC.UTR3GC",
        "xgb_residual",
        "abs_err_xgb",
        "fusion_gain",
    ]
    plot_stats = stats[stats["feature"].isin(selected)].copy()
    plot_stats["abs_delta"] = plot_stats["median_difference_helped_minus_hurt"].abs()
    plot_stats = plot_stats.sort_values("abs_delta", ascending=True)
    fig, ax = plt.subplots(figsize=(8, max(4, 0.35 * len(plot_stats))))
    ax.barh(plot_stats["feature"], plot_stats["median_difference_helped_minus_hurt"], color="#7d9f62")
    ax.axvline(0, color="black", linewidth=0.8)
    ax.set_xlabel("Median difference: helped - hurt")
    ax.set_title("Fusion-helped vs fusion-hurt sample profile")
    fig.tight_layout()
    for ext in ("png", "pdf"):
        fig.savefig(OUT_DIR / f"fusion_gain_helped_vs_hurt_median_differences.{ext}", dpi=220)
    plt.close(fig)


def write_report(group_summary: pd.DataFrame, stats: pd.DataFrame, missing_rates: pd.DataFrame) -> None:
    helped = group_summary[group_summary["fusion_gain_group"] == "fusion_helped_top20"]
    hurt = group_summary[group_summary["fusion_gain_group"] == "fusion_hurt_top20"]
    lines = [
        "# Fusion Gain Sample Profile Report",
        "",
        "Fusion gain is defined as `abs_error_xgb - abs_error_fusion`; positive values mean late fusion improved absolute error.",
        "",
        "Primary grouping in this report uses within-fold top/bottom 20% fusion gain to avoid fold composition artifacts.",
        "",
    ]
    if not helped.empty and not hurt.empty:
        h = helped.iloc[0]
        u = hurt.iloc[0]
        lines.extend(
            [
                "## Group Summary",
                "",
                f"- Within-fold helped top 20%: n={int(h['n'])}, median HALFLIFE={h.get('HALFLIFE_median', float('nan')):.4f}, median XGB residual={h.get('xgb_residual_median', float('nan')):.4f}.",
                f"- Within-fold hurt top 20%: n={int(u['n'])}, median HALFLIFE={u.get('HALFLIFE_median', float('nan')):.4f}, median XGB residual={u.get('xgb_residual_median', float('nan')):.4f}.",
                "",
            ]
        )
    if not missing_rates.empty:
        max_missing = float(missing_rates["missing_rate"].max())
        lines.extend(
            [
                "## BASIC Feature Missingness",
                "",
                f"- Maximum BASIC feature missing rate: {max_missing:.4%}.",
                "",
            ]
        )
    lines.extend(["## Largest Helped-vs-Hurt Median Differences", ""])
    tmp = stats.copy()
    tmp["abs_delta"] = tmp["median_difference_helped_minus_hurt"].abs()
    for row in tmp.sort_values("abs_delta", ascending=False).head(10).itertuples(index=False):
        lines.append(
            f"- `{row.feature}`: helped-hurt median difference = {row.median_difference_helped_minus_hurt:.4f}, "
            f"Cliff's delta = {row.cliffs_delta_helped_vs_hurt:.4f}, p = {row.mannwhitney_p:.3g}, q = {row.q_value_bh_fdr:.3g}"
        )
    (OUT_DIR / "fusion_gain_profile_report.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    print("[CONFIG]", flush=True)
    print(json.dumps(config_dict(), indent=2, ensure_ascii=False), flush=True)
    validate_config_paths()
    cfg = config_dict()
    write_json(OUT_DIR / "fusion_gain_profile_run_config.json", cfg)
    write_json(OUT_DIR / "run_config.json", cfg)

    pred = load_late_fusion_predictions()
    features = load_basic_features(pred["sample_id"].astype(str).tolist())
    df = pred.merge(features, on="sample_id", how="left")
    if "HALFLIFE" in df.columns:
        max_abs = float(np.nanmax(np.abs(pd.to_numeric(df["HALFLIFE"], errors="coerce") - pd.to_numeric(df["y_true"], errors="coerce"))))
        if max_abs > 1e-6:
            raise ValueError(f"HALFLIFE mismatch between late fusion predictions and BASIC table: max_abs={max_abs}")
    else:
        df["HALFLIFE"] = df["y_true"]
    basic_cols = [col for col in df.columns if str(col).startswith("BASIC.")]
    missing_rates = pd.DataFrame(
        {
            "feature": basic_cols,
            "missing_rate": [float(pd.to_numeric(df[col], errors="coerce").isna().mean()) for col in basic_cols],
        }
    )
    missing_rates.to_csv(OUT_DIR / "basic_feature_missing_rates.csv", index=False)
    if not missing_rates.empty and float(missing_rates["missing_rate"].max()) > 0.01:
        print(
            f"[WARN] max BASIC feature missing rate exceeds 1%: {float(missing_rates['missing_rate'].max()):.4%}",
            flush=True,
        )

    df["xgb_residual"] = df["y_true"] - df["xgb_pred"]
    df["fusion_residual"] = df["y_true"] - df["fusion_pred"]
    df["abs_err_xgb"] = np.abs(df["xgb_residual"])
    df["abs_err_fusion"] = np.abs(df["fusion_residual"])
    df["fusion_gain"] = df["abs_err_xgb"] - df["abs_err_fusion"]
    df = assign_gain_groups(df)

    df.to_csv(OUT_DIR / "fusion_gain_sample_profile.csv", index=False)
    group_summary_global = summarize_groups(df, "fusion_gain_group")
    group_summary_within = summarize_groups(df, "fusion_gain_group_within_fold")
    group_summary_global.to_csv(OUT_DIR / "fusion_gain_group_summary_global.csv", index=False)
    group_summary_within.to_csv(OUT_DIR / "fusion_gain_group_summary_within_fold.csv", index=False)
    stats_global = helped_vs_hurt_stats(df, "fusion_gain_group")
    stats_within = helped_vs_hurt_stats(df, "fusion_gain_group_within_fold")
    stats_global.to_csv(OUT_DIR / "fusion_gain_helped_vs_hurt_stats_global.csv", index=False)
    stats_within.to_csv(OUT_DIR / "fusion_gain_helped_vs_hurt_stats_within_fold.csv", index=False)
    df.sort_values("fusion_gain", ascending=False).head(100).to_csv(OUT_DIR / "fusion_gain_top_helped.csv", index=False)
    df.sort_values("fusion_gain", ascending=True).head(100).to_csv(OUT_DIR / "fusion_gain_top_hurt.csv", index=False)

    metric_rows = []
    for model, col in (("xgb", "xgb_pred"), ("mrnalm", "mrnalm_pred"), ("fusion", "fusion_pred")):
        row = {"model": model, "n": len(df)}
        row.update(metrics(df["y_true"].to_numpy(), df[col].to_numpy()))
        metric_rows.append(row)
    pd.DataFrame(metric_rows).to_csv(OUT_DIR / "fusion_gain_overall_model_metrics.csv", index=False)

    save_plots(df, stats_within)
    write_report(group_summary_within, stats_within, missing_rates)
    print(f"[DONE] outputs written to {OUT_DIR}", flush=True)


if __name__ == "__main__":
    main()
